function createCase(storeId='',defaults={}){
 const available=visibleShops().filter(s=>allowed('case.create',s.id));if(!available.length){toast('현재 역할에는 문의 생성 권한이 없습니다.');return;}
 storeId ||= available[0].id;
 formModal('지원 사건 만들기',`${selectField('대상 샵','storeId',available.filter(s=>!defaults.relatedId||s.id===storeId).map(s=>[s.id,s.name]),storeId)}${selectField('분류','category',[['operations','운영'],['order','주문'],['reservation','예약'],['catalog','메뉴'],['identity','직원·권한'],['billing','구독·청구'],['onboarding','샵 준비'],['integration','연동']],defaults.category||'operations')}${field('제목','subject',defaults.subject||'','text','required maxlength="160"')}${selectField('우선순위','priority',['high','medium','low'],'medium')}${selectField('담당자','assignee',[['','미배정'],...state.members.filter(m=>can(state,m.id,'case.update',storeId)).map(m=>[m.id,m.name])],can(state,actorId,'case.update',storeId)?actorId:'')}${field('연결 자료','relatedLabel',defaults.relatedId||storeId,'text',defaults.relatedId?'readonly':'readonly data-current-store-link')}${textarea('요청 내용 · 내부 메모','body',defaults.body||'','required')}`,
 data=>{const result=run('case.create',{storeId:data.storeId,subject:data.subject,category:data.category,priority:data.priority,body:data.body,assignee:data.assignee,relatedType:defaults.relatedType||'store',relatedId:defaults.relatedId||data.storeId});navigate(`support/${result.id}`);return result;},'사건 만들기','가상 문의를 저장합니다. 실제 메일이나 앱 알림은 보내지 않습니다.');
}
