function memberDetail(id){
 const m=state.members.find(x=>x.id===id);if(!m||!allowed('member.read')||!m.countries.every(c=>actor().countries.includes(c)))return toast('해당 계정의 전체 범위를 확인할 권한이 없습니다.');
 openModal('플랫폼 운영자 상세',`${fields([['이름',e(m.name)],['이메일 · 가상',e(m.email)],['역할',e(m.role)],['상태',badge(m.status)],['허용 국가',m.countries.map(c=>countryNames[c]).join(', ')],['샵 범위',e(m.storeIds?.join(', ')||'허용 국가의 전체 샵')]])}<h3 class="mt">접속 세션 · 가상</h3>${table(['기기 / 세션','마지막 접속','상태','회수'],m.sessions.map(s=>[`${e(s.device)}<small>${e(s.id)}</small>`,dt(s.lastSeen),badge(s.active?'active':'suspended',s.active?'활성':'회수됨'),button('회수','session-revoke',`${m.id}|${s.id}`,'secondary small',!s.active||!allowed('member.session.revoke'))]))}${notice('가상 세션 회수는 이 로컬 역할의 사용을 막습니다. 실제 로그인·MFA·접속 세션을 구현한 것은 아닙니다. 권한 변경 승인 시 기존 가상 세션도 회수합니다.')}<div class="form-actions">${button('권한 변경 신청','request-member',m.id,'',!allowed('approval.request:member.permissions')||m.id===actorId)}</div>`,'샵 직원과 별도 관리');
}
function translationDetail(id){
 const t=state.translations.find(x=>x.id===id);if(!t)return;
 openModal('안내 문구 검수',`${fields([['문구 키',e(t.key)],['언어',e(languageNames[t.locale])],['한국어 원문',e(t.source)],['현재 상태',`${badge(t.status)} · v${t.version}`]])}<article class="message mt"><p lang="${t.locale}">${e(t.text)}</p></article><div class="form-actions">${button('초안 편집','translation-edit',t.id,'secondary',!allowed('translation.save'))}${button('번역 게시 신청','request-translation',t.id,'',!allowed('approval.request:translation.publish')||t.status==='published')}</div>`,'준비된 문구 · 실제 AI 통역 미연결');
}
function announcementDetail(id){
 const a=state.announcements.find(x=>x.id===id);if(!a||!(a.country==='all'||actor().countries.includes(a.country)))return;
 openModal(a.title,`${fields([['대상 국가',e(countryNames[a.country]||'전체 허용 국가')],['전달 화면',e(a.channel)],['상태',badge(a.status)],['버전',`v${a.version}`]])}<article class="message mt"><p>${e(a.body)}</p></article>${notice('게시 상태는 데모 안에만 저장됩니다. 실제 이메일·문자·푸시·앱 공지를 전송하지 않습니다.')}<div class="form-actions">${button('초안 수정','announcement-edit',a.id,'secondary',!allowed('announcement.save'))}${button('가상 게시','announcement-publish',a.id,'',a.status!=='draft'||!allowed('announcement.publish'))}</div>`);
}
function announcementForm(id=''){
 const a=state.announcements.find(x=>x.id===id);
 formModal(a?'공지 초안 수정':'샵 공지 작성',`${field('제목','title',a?.title||'','text','required maxlength="160"')}${selectField('대상 국가','country',actor().countries.map(c=>[c,countryNames[c]]),a?.country||actor().countries[0])}${selectField('표시 대상','channel',[['owner','오너 앱'],['staff','직원 앱'],['partner','파트너'],['guest','손님 앱']],a?.channel||'owner')}${textarea('공지 내용','body',a?.body||'','required maxlength="6000"')}`,
 data=>run('announcement.save',{...(a?{id:a.id,expectedVersion:a.version}:{}),...data}),'초안 저장','공지 저장·게시는 가상 처리입니다. 외부 전송은 없습니다.');
}
function openSearch(){openModal('어떤 기록을 찾으세요?',`<label class="field">샵 이름, 주문 번호, 문의 제목<input id="search-all-input" placeholder="예: 주모, ORD, 예약" autocomplete="off"></label><div id="search-all-results" class="mt">${notice('현재 역할과 국가 범위 안에서 찾습니다. 개인정보로 검색하지 않습니다.')}</div>`,'전체 검색');$('#search-all-input').focus();}
function updateSearch(q){
 if(q.length<1){$('#search-all-results').innerHTML=notice('샵 이름이나 기록 번호를 입력해 주세요.');return;}
 const term=q.toLowerCase();const entries=[...visibleShops().map(s=>({title:s.name,meta:`샵 · ${s.id} · ${s.city}`,href:`#shops/${s.id}`})),...list('cases').filter(readableCase).map(c=>({title:c.subject,meta:`지원 사건 · ${c.id}`,href:`#support/${c.id}`})),...list('orders').filter(o=>allowed('diagnostic.read',o.storeId)).map(o=>({title:o.id,meta:`주문 · ${shop(o.storeId)?.name}`,action:'order-detail',id:o.id}))].filter(x=>`${x.title} ${x.meta}`.toLowerCase().includes(term)).slice(0,12);
 $('#search-all-results').innerHTML=entries.length?entries.map(x=>x.href?`<a class="search-result" href="${x.href}" data-close-link><strong>${e(x.title)}</strong><small>${e(x.meta)}</small></a>`:`<button class="search-result full" style="text-align:left;background:white" data-action="${x.action}" data-id="${x.id}"><strong>${e(x.title)}</strong><small>${e(x.meta)}</small></button>`).join(''):empty('검색 결과가 없습니다.');
}
const actions={
 'audit-detail':id=>{const a=state.audit.find(a=>a.id===id);if(!a||!readableAudit(a))return toast('현재 범위에 없는 기록입니다.');openModal('처리 기록 상세',`${fields([['기록 ID',e(a.id)],['처리자',e(a.actor)],['처리 시각',e(dt(a.at))],['업무 종류',e(a.action)],['대상',e(a.target)],['국가·샵',e([a.country,a.storeId].filter(Boolean).join(' / ')||'플랫폼')],['처리 요약',e(a.summary)],['결과',e(a.result)]])}<div class="grid grid-equal mt"><section><h3>변경 전</h3><pre class="code" data-original>${e(a.before?JSON.stringify(a.before,null,2):tr('이 기록에는 변경 전 값이 포함되지 않았습니다.'))}</pre></section><section><h3>변경 후</h3><pre class="code" data-original>${e(a.after?JSON.stringify(a.after,null,2):tr('연결된 업무의 현재 상태를 확인해 주세요.'))}</pre></section></div>${notice('브라우저에 저장된 가상 처리 기록입니다. 실제 운영의 불변 감사 원장은 아닙니다.')}`);},
 'country-check':value=>{const [code,checkId]=value.split('|'),p=state.countryProfiles.find(p=>p.code===code),c=p.checks.find(c=>c.id===checkId);formModal(c.label,`${selectField('검토 결과','status',['pending','done'],c.status)}${textarea('가상 확인 근거','evidence',c.evidence,'required')}`,data=>run('country.check.update',{code,checkId,expectedVersion:p.version||1,...data}),'검토 저장','실제 출시 검증이 아닌 로컬 업무 시연 자료입니다.');},
 'request-country':code=>{const p=state.countryProfiles.find(p=>p.code===code);approvalRequest('country.activation',{...p,id:p.code,version:p.version||1},null,`<div class="span-2 message"><h3>${countryNames[code]} · 검수 ${p.checks.filter(c=>c.status==='done').length}/${p.checks.length}</h3><p>가상 파일럿 활성화를 요청합니다.</p></div>`,'실제 국가별 판매 허가는 아니며 샵 공개 승인은 별도로 진행합니다.');},
 close:closeModal,
 'case-new':id=>createCase(id),
 'case-menu':id=>createCase(id,{subject:'오너 메뉴 수정 검토 요청',category:'catalog',body:'수정이 필요한 메뉴와 사유를 오너에게 확인합니다. 원본 메뉴를 본사에서 덮어쓰지 않습니다.'}),
 'case-staff':id=>createCase(id,{subject:'샵 직원 권한 검토 요청',category:'identity',body:'샵 오너에게 홀·주방 직원의 권한 범위와 변경 동의를 확인합니다.'}),
 'case-onboarding':id=>createCase(id,{subject:'샵 준비 정보 보완 요청',category:'onboarding',body:'미확인 항목과 보완할 증거를 정리해 주세요.'}),
 'case-from-order':id=>{const o=state.orders.find(x=>x.id===id);createCase(o.storeId,{subject:`주문 ${id} 전달 확인`,category:'order',relatedType:'order',relatedId:id,body:'주문 원본을 바꾸지 않고 전달 지연과 알림 상태를 확인합니다.'});},
 'case-from-booking':id=>{const b=state.bookings.find(x=>x.id===id);createCase(b.storeId,{subject:`예약 ${id} 전달 확인`,category:'reservation',relatedType:'booking',relatedId:id,body:'예약 날짜·시간·인원을 샵 오너와 확인합니다.'});},
 'case-edit':id=>{const c=state.cases.find(x=>x.id===id);formModal('지원 사건 담당·상태 변경',`${selectField('담당자','assignee',[['','미배정'],...state.members.filter(m=>can(state,m.id,'case.update',c.storeId)).map(m=>[m.id,m.name])],c.assignee)}${selectField('상태','status',['open','investigating','waiting','resolved'],c.status)}${textarea('변경 메모','note','','required')}`,data=>run('case.update',{id:c.id,expectedVersion:c.version,...data,visibility:'internal'}));},
 profile:id=>{const s=scopedShop(id);formModal('샵 공개 정보 수정',`${field('상호','name',s.name,'text','required maxlength="120"')}${field('도시','city',s.city,'text','required maxlength="120"')}${selectField('기본 언어','locale',[['ko-KR','한국어'],['vi-VN','베트남어'],['en','영어'],['zh','중국어'],['ja','일본어'],['km','크메르어'],['id-ID','인도네시아어'],['lo','라오어'],['hi','힌디어']],s.locale)}${field('영업시간','publicHours',s.publicHours||'17:00–23:00','text','required maxlength="300"')}${textarea('수정 사유','reason','','required')}`,data=>{const {reason,...fields}=data;return run('store.profile.update',{id:s.id,expectedVersion:s.version,fields,reason});},'정보 저장','국가·통화·소유 조직은 여기서 바꿀 수 없습니다. 오너 확인을 받은 공개 정보만 수정하는 가상 흐름입니다.');},
 'check-edit':value=>{const [id,checkId]=value.split('|'),s=scopedShop(id),c=s.onboarding.find(x=>x.id===checkId);formModal(c.label,`${selectField('검토 결과','status',['pending','done'],c.status)}${field('확인 담당','owner',actor().label,'text','readonly')}${textarea('확인한 근거 · 실제 검증 자료 아님','evidence',c.evidence,'required maxlength="1500"')}`,data=>run('onboarding.update',{storeId:s.id,expectedVersion:s.version,checkId,status:data.status,evidence:data.evidence}),'검토 저장','실제 국가별 출시 확인과는 별개인 가상 샵 준비 체크입니다.');},
 'request-intake':id=>{const s=scopedShop(id);approvalRequest('store.intake',s,s.id,selectField('신규 접수 상태','intake',['open','paused','closed'],s.intake),'접수를 다시 열 때는 국가와 샵의 준비 조건을 모두 확인합니다. 기존 주문은 유지합니다.');},
 'request-publication':id=>{const s=scopedShop(id);approvalRequest('store.publication',s,s.id,selectField('공개 상태','publication',['published','review','draft'],s.publication),'국가와 샵의 준비 조건이 갖춰지기 전에는 공개 적용을 차단합니다.');},
 'request-plan':id=>{const s=scopedShop(id);approvalRequest('plan.change',s,s.id,selectField('변경할 플랜','plan',['start','partner','pro'],s.plan),'과거 청구 원금은 바꾸지 않습니다. 국가별 가격은 기획용 예시입니다.');},
 'request-ai':id=>{const s=scopedShop(id);approvalRequest('ai.limit',s,s.id,field(`새 시나리오 할당량 · 현재 사용 ${s.usage}회`,'limit',Math.max(s.limit+500,s.usage+500),'number',`required min="${s.usage+1}" max="1000000" step="1"`),'실제 모델을 켜거나 비용을 청구하지 않습니다.');},
 invoice:invoiceDetail,
 'request-refund':id=>{const i=state.invoices.find(x=>x.id===id);const balance=i.amount-state.refunds.filter(r=>r.invoiceId===id).reduce((a,r)=>a+r.amount,0);approvalRequest('billing.refund',i,i.storeId,field(`가상 환불액 · 잔액 ${money(balance,i.currency)}`,'amount',Math.min(balance,Math.round(i.amount/2)),'number',`required min="1" max="${balance}" step="1"`),'실제 환불은 실행하지 않습니다. 재무 승인 · 리드가 별도로 확인합니다.');},
 'approval-detail':approvalDetail,
 'order-detail':id=>orderDetail(id),
 'booking-detail':id=>orderDetail(id,true),
 collection:id=>{collectionTab=id;render();},
 member:memberDetail,
 'member-invite':()=>formModal('플랫폼 운영자 초대 · 가상',`${field('이름','name','','text','required maxlength="100"')}${field('가상 이메일','email','teammate@example.invalid','email','required')}${selectField('운영 역할','role',roleOptions,'support')}${field('허용 국가 · 쉼표로 구분','countries','VN','text','required')}${field('담당 샵 · 비우면 허용 국가 전체','storeIds','','text','placeholder="예: VN-001,VN-002"')}${notice('국가 파트너는 담당 샵을 지정해야 합니다. 초대 메일 발송·실제 계정 활성화는 하지 않습니다.')}`,data=>run('member.invite',{...data,countries:data.countries.split(',').map(s=>s.trim()).filter(Boolean),storeIds:data.storeIds.trim()?data.storeIds.split(',').map(s=>s.trim()).filter(Boolean):null}),'가상 초대 저장'),
 'request-member':id=>{const m=state.members.find(x=>x.id===id);approvalRequest('member.permissions',m,null,`${selectField('변경할 역할','role',roleOptions,m.role)}${field('허용 국가 · 쉼표 구분','countries',m.countries.join(','),'text','required')}${field('담당 샵 · 비우면 허용 국가 전체','storeIds',m.storeIds?.join(',')||'')}`,'권한 변경이 승인되면 해당 운영자의 가상 세션을 모두 회수합니다. 자기 권한 변경은 신청하거나 승인할 수 없습니다.');},
 'session-revoke':value=>{const [id,sessionId]=value.split('|'),m=state.members.find(x=>x.id===id);formModal('가상 세션 회수',textarea('회수 사유','reason','','required minlength="3"'),data=>run('member.session.revoke',{id,sessionId,expectedVersion:m.version,reason:data.reason}),'세션 회수',`${m.name} · ${sessionId}의 가상 세션을 회수합니다. 다른 실제 기기나 계정에는 영향을 주지 않습니다.`);},
 job:id=>{const j=state.jobs.find(x=>x.id===id);formModal('실패 작업 재시도 대기',`${field('유지할 작업 번호','operationId',j.operationId,'text','readonly')}${textarea('재시도 사유','reason','','required minlength="3"')}`,data=>run('job.retry',{id,reason:data.reason}),'대기열에 넣기','동일한 작업 번호를 유지해 가상 재시도 대기에 넣습니다. 외부 연동 호출이나 성공 확정은 하지 않습니다.');},
 incident:id=>{const i=state.incidents.find(x=>x.id===id);formModal('장애 대응 상태 기록',`${selectField('상태','status',['investigating','monitoring','resolved'],i.status)}${textarea('확인 결과와 다음 조치','note','','required minlength="3"')}`,data=>run('incident.update',{id,expectedVersion:i.version,...data}),'대응 기록 저장','조사 → 복구 관찰 → 해결 순서로 확인합니다. 해결한 사건은 재조사로 다시 열 수 있습니다.');},
 integration:id=>{const i=state.integrations.find(x=>x.id===id);if(!i||i.storeId&&!scopeRecord(i,'diagnostic.read'))return;openModal('연동 진단 상세',`${fields([['연동',e(i.name)],['제공자',e(i.provider)],['대상 샵',e(shop(i.storeId)?.name||countryNames[i.country])],['상태',badge(i.status,i.status==='open'?'청구 예정':labels[i.status])],['마지막 동기화',dt(i.lastSync)],['지연 예시',`${i.latencyMs} ms`]])}<h3 class="mt">관련 작업</h3>${table(['작업','상태','시도','처리'],state.jobs.filter(j=>j.integrationId===id&&visibleIds().has(j.storeId)).map(j=>[e(j.id),badge(j.status),String(j.attempts),button('재시도','job',j.id,'secondary small',j.status!=='failed'||!allowed('job.retry',j.storeId))]))}${notice('제공자와 지연은 가상 값입니다. 실제 POS·메일·결제 서버는 연결하지 않았습니다.')}`);},
 translation:translationDetail,
 'translation-edit':id=>{const t=state.translations.find(x=>x.id===id);formModal(`${languageNames[t.locale]} 문구 초안`,`${field('한국어 원문','source',t.source,'text','readonly')}${textarea('번역 문구','text',t.text,'required maxlength="4000"')}`,data=>run('translation.save',{id,expectedVersion:t.version,text:data.text}),'초안 저장','저장하면 초안이 됩니다. 게시하려면 다른 담당자의 승인이 필요합니다.');},
 'request-translation':id=>{const t=state.translations.find(x=>x.id===id);approvalRequest('translation.publish',t,null,`<div class="span-2 message"><h3>${e(languageNames[t.locale])} · ${e(t.key)}</h3><p lang="${t.locale}">${e(t.text)}</p></div>`);},
 announcement:announcementDetail,
 'announcement-new':()=>announcementForm(),
 'announcement-edit':announcementForm,
 'announcement-publish':id=>{const a=state.announcements.find(x=>x.id===id);formModal('공지 가상 게시',textarea('게시 사유','reason','','required minlength="3"'),data=>run('announcement.publish',{id,expectedVersion:a.version,reason:data.reason}),'가상 게시','실제 공지·메일·푸시는 발송하지 않습니다.');},
 export:()=>{if(!exportContext)return;const ctx=exportContext;const result=run('export.record',{resource:ctx.resource,storeId:null,count:ctx.rows.length,fields:ctx.fields});const csvCell=value=>{let text=String(value??'');if(/^[=+@\-\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};const csv='\uFEFF'+[ctx.fields.map(csvCell).join(','),...ctx.rows.map(row=>ctx.fields.map(f=>csvCell(row[f])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`one-shop-admin-${ctx.resource}-demo.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);render();toast(result.message);}
};

$('#language').addEventListener('change',event=>setLanguage(event.target.value));
$('#role').innerHTML=ACTORS.map(a=>`<option value="${a.id}">${e(a.label)}</option>`).join('');
$('#menu-toggle').innerHTML=icon('menu');$('#dialog-close').innerHTML=icon('close');$('#search-icon').innerHTML=icon('search');
$('#menu-toggle').addEventListener('click',()=>setNav(!document.body.classList.contains('nav-open')));
$('#nav-shade').addEventListener('click',()=>setNav(false));
$('#dialog-close').addEventListener('click',closeModal);
$('#detail-dialog').addEventListener('close',()=>{modalSubmit=null;});
$('#global-search').addEventListener('click',openSearch);
$('#refresh-button').addEventListener('click',()=>{try{const disk=JSON.parse(localStorage.getItem(STORAGE));if(disk?.schemaVersion===2)state=migrateDemo(disk);}catch{}render();toast('저장된 로컬 자료를 다시 불러왔습니다.');});
$('#role').addEventListener('change',event=>{closeModal();actorId=event.target.value;sessionStorage.setItem('oneshop-admin-actor',actorId);country='all';$('#country').value='all';render();toast(`${actor().label} 역할로 미리봅니다.`);});
$('#country').addEventListener('change',event=>{country=event.target.value;Object.values(filters).forEach(f=>f.page=1);render();});
$('#reset').addEventListener('click',()=>{
 const word={ko:'초기화',en:'RESET',vi:'ĐẶT LẠI'}[lang];
 formModal(tr('데모 데이터 초기화'),field(tr('확인 문구')+': '+word,'confirm','','text','required'),data=>{if(data.confirm.trim()!==word)throw new Error(tr('확인 문구를 그대로 입력해 주세요.'));state=migrateDemo(createSeed());state.generation=crypto.randomUUID();actorId='ops-min';country='all';$('#country').value='all';sessionStorage.setItem('oneshop-admin-actor',actorId);save();navigate('overview');return {message:tr('가상 데이터와 처리 기록을 초기화했습니다.')};},tr('데모 초기화'),tr('이 브라우저에서 만든 가상 문의·승인·처리 기록만 지워집니다. 원샵의 실제 앱과 주문에는 영향이 없습니다.'));
});

let filterTimer;
document.addEventListener('input',event=>{
 if(event.target.id==='search-all-input'){updateSearch(event.target.value);return;}
 const key=event.target.dataset.filterQuery;if(!key)return;fstate(key).q=event.target.value;fstate(key).page=1;const position=event.target.selectionStart;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{render();const input=document.querySelector(`[data-filter-query="${key}"]`);if(input){input.focus();input.setSelectionRange(position,position);}},180);
});
document.addEventListener('change',event=>{if(event.target.name==='storeId'&&event.target.closest('#action-form')){const target=event.target.closest('form').querySelector('[name=assignee]');const related=event.target.closest('form').querySelector('[data-current-store-link]');if(related)related.value=event.target.value;if(target)target.innerHTML=options([['','미배정'],...state.members.filter(m=>can(state,m.id,'case.update',event.target.value)).map(m=>[m.id,m.name])]);}
 localize(event.target.closest('form')||event.target,lang);const key=event.target.dataset.filterStatus;if(key){fstate(key).status=event.target.value;fstate(key).page=1;render();}});
document.addEventListener('click',event=>{
 const target=event.target.closest('[data-action]');if(target&&!target.disabled){const fn=actions[target.dataset.action];if(fn){event.preventDefault();try{fn(target.dataset.id||'');}catch(error){toast(error.message);}}else{try{if(handleAdvanced(target.dataset.action,target.dataset.id||'',advancedContext()))event.preventDefault();}catch(error){toast(error.message);}}}
 const page=event.target.closest('[data-page]');if(page){fstate(page.dataset.page).page+=Number(page.dataset.delta);render();}
 if(event.target.closest('[data-close-link]'))closeModal();
});
document.addEventListener('submit',event=>{
 if(event.target.id==='action-form'){
  event.preventDefault();if(!modalSubmit)return;const form=event.target;const errorBox=$('#form-error');try{const result=modalSubmit(Object.fromEntries(new FormData(form)));closeModal();render();toast(result?.message||'가상 자료에 저장했습니다.');}catch(error){errorBox.textContent=tr(error.message);errorBox.hidden=false;errorBox.scrollIntoView({block:'nearest'});}
 }
 if(event.target.id==='case-note-form'){
  event.preventDefault();const c=state.cases.find(x=>x.id===event.target.dataset.id);try{const result=run('case.update',{id:c.id,expectedVersion:c.version,...Object.fromEntries(new FormData(event.target))});render();toast(result.message);}catch(error){$('#case-inline-error').textContent=tr(error.message);$('#case-inline-error').hidden=false;}
 }
});
window.addEventListener('hashchange',()=>{setNav(false);closeModal();render();window.scrollTo(0,0);});
window.addEventListener('storage',event=>{
 if(event.key!==STORAGE)return;
 try {
  const disk=JSON.parse(event.newValue);if(disk?.schemaVersion!==2)return;
  const identity=s=>JSON.stringify(s.members.find(m=>m.id===actorId));
  if(identity(disk)!==identity(state)||disk.generation!==state.generation){
   closeModal();state=migrateDemo(disk);country='all';$('#country').value='all';Object.keys(filters).forEach(key=>delete filters[key]);render();toast('계정 범위 또는 데모 자료가 바뀌어 열린 상세를 닫고 접근 범위를 다시 확인했습니다.');return;
  }
  if($('#detail-dialog').open||document.activeElement?.closest('form')){toast('다른 탭에서 자료가 바뀌었습니다. 작성 중인 내용을 확인한 뒤 새로고침해 주세요.');return;}
  state=migrateDemo(disk);render();toast('다른 탭의 로컬 변경을 반영했습니다.');
 }catch{}
});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='Escape'&&document.body.classList.contains('nav-open'))setNav(false);});
try{render();save();}catch(error){$('#content').innerHTML=`<section class="card restricted"><h2>저장된 체험 자료를 확인해 주세요.</h2><p>${e(error.message)}</p><p>아래 ‘데모 데이터 초기화’로 가상 자료를 다시 시작할 수 있습니다.</p></section>`;}
